<x-admin-layout :title="ucfirst($resource)"><div class="checkout-grid"><section><h2>{{ $record->exists?'Edit entry':'New entry' }}</h2><form method="post" enctype="multipart/form-data" action="/admin/content/{{ $resource }}{{ $record->exists?'/'.$record->id:'' }}">@csrf @php($fields=match($resource){'categories'=>['name','slug','description','parent_id','position','seo_title','meta_description','canonical_url'],'pages'=>['title','slug','content','seo_title','meta_description','canonical_url','og_title','og_description'],'blog'=>['title','slug','author','excerpt','content','published_at','seo_title','meta_description'],'coupons'=>['code','type','percent','amount','minimum','maximum_discount','usage_limit','per_customer_limit','starts_at','expires_at','product_id','category_id']})@foreach($fields as $field)<label>{{ ucfirst(str_replace('_',' ',$field)) }}@if($field==='type')<select name="type"><option value="percent" @selected(old('type',$record->type??'percent')==='percent')>Percentage</option><option value="fixed" @selected(old('type',$record->type)==='fixed')>Fixed amount in paisa</option></select>@elseif($field==='parent_id')<select name="parent_id"><option value="">Top-level category</option>@foreach($categoryOptions->whereNull('parent_id')->where('id','!=',$record->id) as $category)<option value="{{ $category->id }}" @selected(old('parent_id',$record->parent_id)==$category->id)>{{ $category->name }}</option>@endforeach</select>@elseif($field==='category_id')<select name="category_id"><option value="">All categories</option>@foreach($categoryOptions as $category)<option value="{{ $category->id }}" @selected(old('category_id',$record->category_id)==$category->id)>{{ $category->name }}</option>@endforeach</select>@elseif($field==='product_id')<select name="product_id"><option value="">All products</option>@foreach($productOptions as $product)<option value="{{ $product->id }}" @selected(old('product_id',$record->product_id)==$product->id)>{{ $product->name }}</option>@endforeach</select>@elseif(in_array($field,['description','content','excerpt','meta_description']))<textarea name="{{ $field }}" rows="{{ $field==='content'?10:3 }}">{{ old($field,$record->$field) }}</textarea>@else<input name="{{ $field }}" value="{{ old($field,$record->$field) }}" @if(in_array($field,['percent','amount','minimum','maximum_discount','usage_limit','per_customer_limit','product_id','category_id','parent_id','position']))type="number" min="0" @endif @if(in_array($field,['published_at','starts_at','expires_at']))placeholder="YYYY-MM-DD HH:MM:SS"@endif>@endif</label> @endforeach @if(in_array($resource,['categories','blog']))@if($record->image)<div class="media-preview"><img src="{{ Storage::url($record->image) }}" alt="Current content image" width="220"><label class="check"><input type="checkbox" name="remove_image" value="1">Remove current image</label></div>@endif<label>Image (JPEG, PNG, WebP; 4 MB max)<input type="file" name="image_upload" accept="image/jpeg,image/png,image/webp"></label>@endif @if(in_array($resource,['categories','pages']))<label class="check"><input type="checkbox" name="published" value="1" @checked(old('published',$record->published))>Published</label>@elseif($resource==='coupons')<label class="check"><input type="checkbox" name="active" value="1" @checked(old('active',$record->active))>Active</label><p class="small">Amounts are in paisa. Type must be percent or fixed. Product/category IDs restrict eligibility; leave blank for the whole bag. Limits are checked under a database lock.</p>@endif<p class="small">Content is displayed as safe plain text with line breaks. Policies must be reviewed and approved by the business owner before launch.</p><button class="button">Save entry ↗</button></form>@if($resource==='categories'&&$record->exists)<p><a href="/category/{{ $record->slug }}" class="text-link">Preview published category ↗</a></p><form method="post" action="/admin/content/categories/{{ $record->id }}/delete">@csrf<button class="button button-light" data-confirm="Delete this empty category? Products and nested categories must be moved first.">Delete empty category</button></form><p class="small">Parent ID must reference a top-level category; see the ID list. Category ID: {{ $record->id }}</p>@endif @if($resource==='coupons'&&$record->exists)<p>Used {{ $record->used }} of {{ $record->usage_limit }} times. Total discount applied: {{ \App\Services\Settings::money((int)$redemptionTotal) }}.</p>@endif</section><aside><div class="section-head"><h2>Entries</h2><a href="/admin/content/{{ $resource }}">New +</a></div>@foreach($records as $entry)<a class="content-entry" href="/admin/content/{{ $resource }}/{{ $entry->id }}">#{{ $entry->id }} · {{ $entry->name??$entry->title??$entry->code }} ↗</a>@endforeach{{ $records->links() }}</aside></div></x-admin-layout>